class Solution { public:
 vector<string> getWordsInLongestSubsequence(vector<string>& words,vector<int>& groups){
  int n=words.size();vector<int> dp(n,1),par(n,-1);int best=0;
  for(int i=0;i<n;++i){for(int j=0;j<i;++j){if(groups[i]==groups[j]||words[i].size()!=words[j].size())continue;
   int diff=0;for(int t=0;t<(int)words[i].size();++t)diff+=words[i][t]!=words[j][t];
   if(diff==1 && dp[j]+1>dp[i]){dp[i]=dp[j]+1;par[i]=j;}}
   if(dp[i]>dp[best])best=i;
  }
  vector<string> ans;for(int i=best;i!=-1;i=par[i])ans.push_back(words[i]);reverse(ans.begin(),ans.end());return ans;
 }
};
